// Act Natural!: The Oxford Method, Book 2 (A1+). One conversation for each unit of the book,
// made from the unit's dialogue (Read. Cover. Respond.) and its partner task (cards A and B).
//
// Each unit has the two roles of the game:
//   turns + end   the other person speaks first and the student answers (same format as T in scenes.js)
//   staff + bye   the student starts the conversation and asks (same format as W in staff.js):
//                 5 lines that mirror the other person's lines above; the other person answers with the model answers.

const BOOK = [];
const BOOK_COLORS = ["#c8323c", "#2d8cf0", "#14a35a", "#f2a100", "#9b51e0", "#e8590c", "#0b9ea8"];
function UNIT(o){
  BOOK.push({ id: "b2u" + o.unit, unit: o.unit, book: true, name: o.name, icon: o.icon, who: o.who, face: o.face,
    color: BOOK_COLORS[(o.unit - 1) % BOOK_COLORS.length], leave: o.leave || "Sorry, I have to go. Bye!",
    levels: { "A1+": { turns: o.turns, end: o.end } } });
  STAFF["b2u" + o.unit] = { client: o.client, face: o.cface, leave: o.cleave || "Never mind. I'll ask someone else.",
    bye: { "A1+": o.bye }, "A1+": o.staff };
}

/* ===================== MODULE 1 / Everyday English ===================== */
UNIT({ unit: 1, name: "What have you got?", icon: "🎒", who: "Classmate", face: "👩", client: "Friend", cface: "🧔",
  turns: [
    T("Hi! Have you got the tickets for the visit?", "Say yes: you've got two tickets.", "Yes, I have. I've got two tickets.|Yes, I've got two tickets.", "yes ; two/2 ; ticket",
      "Yes, I have got. :: In short answers, don't use 'got': Yes, I have.", "Yes, I have two ticket. :: Two tickets: plural with -s."),
    T("Great. Has Sam got his charger?", "Say no, he hasn't. Say you've got a charger.", "No, he hasn't. I've got a charger.|No, he hasn't, but I've got one.", "no ; hasnt/has not",
      "No, he hasn't got. :: Short answer: No, he hasn't.", "No, he don't have. :: With he: No, he hasn't."),
    T("I've got a water bottle and a notebook. Have you got everything?", "Say no, and ask to borrow their water bottle.", "No, I haven't. Can I borrow your water bottle?|No. Can I borrow your water bottle, please?", "borrow ; water/bottle",
      "Can I lend your water bottle? :: Borrow = take; lend = give. Say: Can I borrow…?", "I can borrow your water bottle? :: In questions the verb goes first: Can I borrow…?", "q"),
    T("Yes, of course. Can I borrow your charger?", "Say yes, of course, and give it to them.", "Yes, of course. Here you are.|Of course. Here you are.", "here",
      "Yes, of course. Here you have. :: When you give something, say 'Here you are'.", "Yes, take. :: When you give something, say 'Here you are'."),
  ], end: "Thanks! See you at the art gallery at ten.",
  staff: [
    W("Ask your friend if they've got the tickets for the visit.", "Have you got the tickets for the visit?|Have you got the tickets?", "have ; ticket",
      "You have got the tickets? :: In questions put 'have' first: Have you got…?", "Do you have got the tickets? :: Don't mix: Have you got…? or Do you have…?", "q"),
    W("Ask if Sam has got his charger.", "Has Sam got his charger?|Has Sam got a charger?", "has ; sam ; charger",
      "Have Sam got his charger? :: With he / she use 'has': Has Sam got…?", "Sam has got his charger? :: In questions put 'has' first: Has Sam got…?", "q"),
    W("Say you've got a water bottle and a notebook. Ask if they've got everything.", "I've got a water bottle and a notebook. Have you got everything?", "water/notebook ; everything",
      "I have a water bottle and a notebook. You have everything? :: Question: Have you got everything?", "I've got a water bottle and a notebook. Have you got all? :: Say 'everything'.", "q"),
    W("Say yes, give it, and ask to borrow their charger.", "Yes, of course. Here you are. Can I borrow your charger?|Here you are. Can I borrow your charger?", "here ; borrow ; charger",
      "Yes. Here you are. Can I lend your charger? :: Borrow = take; lend = give. Say: Can I borrow…?", "Yes, of course. Take. Can I borrow your charger? :: When you give something, say 'Here you are'.", "q"),
    W("Thank them and say: see you at the art gallery at ten.", "Thanks! See you at the art gallery at ten.|Thank you! See you at the gallery at ten.", "thank ; see ; ten/10",
      "Thanks! We see at the gallery at ten. :: Say 'See you…'.", "Thanks! See you at the gallery to the ten. :: Times: at ten."),
  ], bye: "Bye! See you there!" });

UNIT({ unit: 2, name: "What time is it?", icon: "🕒", who: "Classmate", face: "👨", client: "Friend", cface: "👩",
  turns: [
    T("Hi! We need a 30-minute meeting next week. Are you free on Tuesday?", "Say yes: you're free from 10 to 11.", "Yes, I'm free from ten to eleven.|Yes. I'm free from 10 to 11.", "free ; ten/10 ; eleven/11",
      "Yes, I am free of ten to eleven. :: Say 'from … to …'.", "Yes, I'm free since ten until eleven. :: For times use 'from … to …'."),
    T("Oh, I'm free from half past eleven. What about Thursday?", "Say you're free from 3 to 5 p.m. on Thursday.", "I'm free from three to five on Thursday.|On Thursday I'm free from three to five.", "free ; three/3/15 ; five/5/17",
      "Thursday I'm free from the three to the five. :: No 'the' with times: from three to five.", "I'm free on Thursday at three to five. :: Say 'from three to five'."),
    T("Great, I'm free from four. Let's meet at four o'clock.", "Ask where you can meet.", "OK. Where can we meet?|Great. Where shall we meet?", "where",
      "Where we can meet? :: Question order: Where can we meet?", "Where meet? :: Make a full question: Where can we meet?", "q"),
    T("At the cafe. It closes at five.", "Say: OK, see you on Thursday at four.", "OK. See you on Thursday at four.|Great, see you on Thursday at four.", "see ; thursday ; four/4",
      "OK, we see on Thursday at four. :: Say 'See you…'.", "OK, see you the Thursday at the four. :: On Thursday, at four: no 'the'."),
  ], end: "Perfect. See you then!",
  staff: [
    W("Say you need a 30-minute meeting. Ask if your friend is free on Tuesday.", "We need a 30-minute meeting. Are you free on Tuesday?|Are you free on Tuesday? We need a thirty-minute meeting.", "free ; tuesday",
      "We need a 30-minute meeting. You are free on Tuesday? :: In questions the verb goes first: Are you free…?", "We need a 30-minute meeting. Are you free the Tuesday? :: Days: on Tuesday.", "q"),
    W("Say you're free from half past eleven. Ask about Thursday.", "I'm free from half past eleven. What about Thursday?|I'm free from 11:30. What about Thursday?", "half past/11 30/eleven thirty ; thursday",
      "I'm free from eleven and half. What about Thursday? :: Say 'half past eleven'.", "I'm free from half past eleven. And the Thursday? :: Say 'What about Thursday?'.", "q"),
    W("Say you're free from four. Suggest meeting at four o'clock.", "I'm free from four. Let's meet at four o'clock.|I'm free from four, so let's meet at four.", "four/4 ; lets/shall we/what about",
      "I'm free from four. We meet at four? :: To suggest something, say 'Let's meet at four'.", "I'm free since four. Let's meet at four. :: Say 'from four'."),
    W("Say: at the cafe. It closes at five.", "At the cafe. It closes at five.|We can meet at the cafe. It closes at five.", "cafe/caf ; five/5/17",
      "In the cafe. It close at five. :: It closes (with -s).", "At the cafe. It closes to five. :: Times: at five."),
    W("Say perfect, see you then.", "Perfect. See you then!|Great. See you then!", "see",
      "Perfect. We see then! :: Say 'See you then!'.", "Perfect. See you after! :: Say 'See you then' or 'See you later'."),
  ], bye: "Bye!" });

UNIT({ unit: 3, name: "What would you like to do?", icon: "🎨", who: "Friend", face: "👩", client: "Classmate", cface: "👦",
  turns: [
    T("Hi! What do you enjoy doing at the weekend?", "Say you enjoy art and cooking.", "I enjoy art and cooking.|I enjoy cooking and art.", "enjoy/like/love ; art ; cook",
      "I enjoy to cook and art. :: After 'enjoy' use -ing: I enjoy cooking.", "I am enjoy art and cooking. :: No 'am': I enjoy…"),
    T("Nice! I enjoy walks and photography. Are you free on Saturday morning?", "Say yes, and invite them to visit the museum.", "Yes, I am. Would you like to visit the museum?|Yes. Would you like to visit the museum with me?", "would you like/do you want/shall we ; museum",
      "Yes. Would you like visit the museum? :: Would you like + to: to visit.", "Yes. You would like to visit the museum? :: Question order: Would you like…?", "q"),
    T("Hmm, I'd prefer to go for a walk. Maybe in the park?", "Agree: say that sounds good.", "That sounds good.|OK, that sounds good!", "good/great/nice/fine",
      "That sounds well. :: Say 'That sounds good'.", "It sound good. :: It sounds (with -s)."),
    T("Great! What time?", "Suggest ten o'clock at the park entrance.", "Let's meet at ten at the park entrance.|What about ten o'clock at the park entrance?", "ten/10 ; park/entrance",
      "We meet at the ten. :: No 'the': at ten. And suggest: Let's meet at ten.", "Let's meet in ten. :: Times: at ten."),
  ], end: "Perfect. See you on Saturday!",
  staff: [
    W("Ask your classmate what they enjoy doing at the weekend.", "What do you enjoy doing at the weekend?|What do you like doing at the weekend?", "what ; enjoy/like",
      "What you enjoy doing at the weekend? :: Questions need 'do': What do you enjoy…?", "What do you enjoy to do at the weekend? :: After 'enjoy' use -ing: doing.", "q"),
    W("Say you enjoy walks and photography. Ask if they're free on Saturday morning.", "I enjoy walks and photography. Are you free on Saturday morning?", "walk/photo ; free ; saturday",
      "I enjoy walks and photography. You are free on Saturday morning? :: Question: Are you free…?", "I enjoy walks and photography. Are you free the Saturday morning? :: Say 'on Saturday morning'.", "q"),
    W("Say you'd prefer to go for a walk in the park.", "I'd prefer to go for a walk in the park.|I'd prefer to walk in the park.", "prefer ; walk ; park",
      "I would prefer walk in the park. :: Add 'to': I'd prefer to walk.", "I prefer go for a walk in the park. :: Say 'I'd prefer to go…'."),
    W("Say great, and ask what time.", "Great! What time?|Great! What time shall we meet?", "what time",
      "Great! Which hour? :: Say 'What time?'.", "Great! At what time we meet? :: Say: What time shall we meet?", "q"),
    W("Say perfect, see you on Saturday.", "Perfect. See you on Saturday!|Great. See you on Saturday!", "see ; saturday",
      "Perfect. See you the Saturday! :: Days: on Saturday.", "Perfect. We see on Saturday! :: Say 'See you…'."),
  ], bye: "See you!" });

UNIT({ unit: 4, name: "Staying in touch", icon: "💻", who: "Classmate", face: "👦", client: "Friend", cface: "👩",
  turns: [
    T("Hi! What are you doing?", "Say you're trying to open the timetable link.", "I'm trying to open the timetable link.|I'm trying to open the link for the timetable.", "trying ; link",
      "I try to open the timetable link. :: For now, use am + -ing: I'm trying.", "I am trying open the link. :: try + to: I'm trying to open."),
    T("Oh. Does it open?", "Say no, it doesn't. Ask for help.", "No, it doesn't. Could you help me, please?|No, it doesn't. Can you help me, please?", "no ; help",
      "No, it doesn't. You can help me? :: Question order: Can you help me?", "No, it don't. Could you help me, please? :: With it: it doesn't.", "pq"),
    T("Sure. I haven't got it on my phone, but I've got the timetable on paper.", "Ask if you can borrow it.", "Can I borrow it, please?|Could I borrow the timetable, please?", "borrow",
      "Can you borrow me the timetable? :: Say: Can I borrow…? or Can you lend me…?", "I can borrow it, please? :: In questions the verb goes first: Can I borrow…?", "pq"),
    T("Here you are. Can I borrow your charger? My phone is dead.", "Say sorry, you need it now. Offer a pen.", "Sorry, I need it now. But you can borrow my pen.|Sorry, I need my charger. Would you like a pen?", "sorry ; need ; pen",
      "Sorry, I am needing it. :: 'need' doesn't take -ing here: I need it.", "Sorry, I need it. But I can borrow you a pen. :: Lend = give: I can lend you a pen."),
  ], end: "No problem. Thanks!",
  staff: [
    W("Ask your friend what they're doing.", "What are you doing?|Hi! What are you doing?", "what ; doing",
      "What do you do? :: For right now: What are you doing?", "What you are doing? :: Question order: What are you doing?", "q"),
    W("Ask if the link opens.", "Does it open?|Does the link open?", "does ; open",
      "It opens? :: Question: Does it open?", "Do it open? :: With it: Does it…?", "q"),
    W("Say sure. You haven't got it on your phone, but you've got the timetable on paper.", "Sure. I haven't got it on my phone, but I've got the timetable on paper.|Sure. It isn't on my phone, but I've got it on paper.", "phone ; paper",
      "Sure. I don't have got it on my phone, but I have it on paper. :: Say: I haven't got it.", "Sure. I haven't got it on my phone, but I've got the timetable in paper. :: Say 'on paper'."),
    W("Give it. Ask to borrow their charger.", "Here you are. Can I borrow your charger?|Here you are. Can I borrow your charger, please?", "here ; borrow ; charger",
      "Here you have. Can I borrow your charger? :: Say 'Here you are'.", "Here you are. Can you borrow me your charger? :: Say: Can I borrow…? / Can you lend me…?", "q"),
    W("Say no problem, and thanks.", "No problem. Thanks!|That's OK. Thanks anyway!", "problem/ok/okay ; thank",
      "No problem. Thank! :: Say 'Thanks' or 'Thank you'.", "Is no problem. Thanks! :: Say 'No problem'."),
  ], bye: "You're welcome!" });

UNIT({ unit: 5, name: "At the shops", icon: "👕", who: "Shop assistant", face: "👩‍💼", client: "Customer", cface: "🧔",
  turns: [
    T("Hello! Can I help you?", "Say you'd like a jumper.", "Yes, I'd like a jumper, please.|Yes, please. I'd like a jumper.", "jumper/sweater",
      "Yes, I want a jumper. :: 'I want' is too direct: I'd like a jumper, please.", "Yes, I'd like a jersey, please. :: In English it's a jumper ('jersey' is Spanish!).", "p"),
    T("We've got blue jumpers for £24 and green ones for £28. What size?", "Ask for the blue one in medium.", "The blue one in medium, please.|Have you got the blue one in medium?", "blue ; medium",
      "The blue in medium. :: Say 'the blue one'.", "The blue one in size middle. :: Sizes: small, medium, large."),
    T("Yes. Here you are. Anything else?", "Say you need some socks. Ask how much they are.", "Yes, I need some socks. How much are they?|Some socks, please. How much are they?", "socks ; how much",
      "I need some socks. How much cost? :: Say: How much are they?", "I need some socks. How many are they? :: For prices: How much…?", "q"),
    T("Socks are £7. That's £31 altogether.", "Ask if you can pay by card.", "Can I pay by card?|Can I pay contactless?", "pay ; card/contactless",
      "Can I pay with card? :: We say 'by card'.", "I can pay by card? :: Question order: Can I pay…?", "q"),
  ], end: "Yes, of course. Here's your receipt.",
  staff: [
    W("Greet the customer and ask if you can help.", "Hello! Can I help you?|Hello! How can I help you?", "help",
      "Hello! You need help? :: Say: Can I help you?", "Hello! What do you want? :: Too direct. Say: Can I help you?", "q"),
    W("Say blue jumpers are £24 and green ones are £28. Ask what size.", "We've got blue jumpers for £24 and green ones for £28. What size?|Blue jumpers are £24 and green ones are £28. What size are you?", "24/twenty four ; 28/twenty eight ; size",
      "Blue jumpers are £24 and green ones are £28. What size you are? :: Question order: What size are you?", "Blue jumpers are 24 pound and green ones are 28 pound. What size? :: Say 'pounds': twenty-four pounds.", "q"),
    W("Say yes, give it, and ask if they want anything else.", "Yes. Here you are. Anything else?|Here you are. Would you like anything else?", "here ; else",
      "Yes. Here you have. Something more? :: Say 'Here you are' and 'Anything else?'.", "Here you are. You want other thing? :: Say: Would you like anything else?", "q"),
    W("Say socks are £7, and the total is £31.", "Socks are £7. That's £31 altogether.|They're seven pounds. That's thirty-one pounds altogether.", "7/seven ; 31/thirty one",
      "Socks are £7. Is £31 all. :: Say: That's £31 altogether.", "Socks costs £7. That's £31 altogether. :: Socks cost (plural, no -s)."),
    W("Say yes, of course, and give the receipt.", "Yes, of course. Here's your receipt.|Of course. Here you are, and here's your receipt.", "receipt",
      "Yes, of course. Here is your recipe. :: A recipe is for cooking! Say 'receipt'.", "Yes, of course. Here's your ticket of the shop. :: Say 'your receipt'."),
  ], bye: "Thank you! Bye!" });

/* ===================== MODULE 2 / People, places and experiences ===================== */
UNIT({ unit: 6, name: "Choosing a day out", icon: "🌳", who: "Friend", face: "👩", client: "Classmate", cface: "👨",
  turns: [
    T("Let's go out on Saturday! The museum or the garden?", "Ask which place is cheaper.", "Which place is cheaper?|Which one is cheaper?", "which/what ; cheaper",
      "Which place is more cheap? :: Short adjectives: cheaper.", "Which place is the more cheap? :: Say: Which place is cheaper?", "q"),
    T("The garden is £6 and the museum is £9.", "Say the garden is cheaper than the museum.", "The garden is cheaper than the museum.|So the garden is cheaper than the museum.", "garden ; cheaper ; than",
      "The garden is cheaper that the museum. :: Comparisons use 'than'.", "The garden is more cheap than the museum. :: Say 'cheaper'."),
    T("Yes, but the museum is nearer. It's ten minutes, and the garden is fifteen.", "Ask which option your friend prefers.", "Which option do you prefer?|Which one do you prefer?", "which/what ; prefer",
      "Which option you prefer? :: Questions need 'do': Which option do you prefer?", "Which option are you prefer? :: Say: Which option do you prefer?", "q"),
    T("The museum. It's more comfortable in the rain. And you?", "Say you prefer the museum because it's nearer.", "I prefer the museum because it's nearer.|Me too. I prefer the museum because it's nearer.", "prefer ; museum ; because ; nearer/near/closer",
      "I prefer the museum because is nearer. :: It needs a subject: because it's nearer.", "I prefer the museum because it's more near. :: Say 'nearer'."),
  ], end: "Great! Shall we meet at ten?",
  staff: [
    W("Suggest going out on Saturday. Ask: the museum or the garden?", "Let's go out on Saturday! The museum or the garden?|Shall we go out on Saturday? The museum or the garden?", "saturday ; museum ; garden",
      "We go out the Saturday? The museum or the garden? :: Suggest with 'Let's…', and say 'on Saturday'.", "Let's to go out on Saturday! The museum or the garden? :: After 'Let's' no 'to': Let's go out."),
    W("Say the garden is £6 and the museum is £9.", "The garden is £6 and the museum is £9.|The garden is six pounds, and the museum is nine.", "6/six ; 9/nine",
      "The garden is £6 and the museum are £9. :: One museum: the museum is.", "The garden costs 6 pound and the museum 9 pound. :: Say 'pounds' (plural)."),
    W("Say yes, but the museum is nearer: 10 minutes. The garden is 15.", "Yes, but the museum is nearer. It's ten minutes, and the garden is fifteen.|Yes, but the museum is nearer: 10 minutes. The garden is 15.", "nearer/closer ; 10/ten ; 15/fifteen",
      "Yes, but the museum is more near. It's ten minutes. :: Say 'nearer'.", "Yes, but the museum is nearest. It's ten minutes and the garden fifteen. :: For two things: nearer (not nearest)."),
    W("Say you prefer the museum: it's more comfortable in the rain. Ask: and you?", "The museum. It's more comfortable in the rain. And you?|I prefer the museum. It's more comfortable in the rain. What about you?", "museum ; comfortable ; you",
      "The museum. It's comfortabler in the rain. And you? :: Long adjectives: more comfortable.", "The museum. Is more comfortable in the rain. And you? :: It needs a subject: It's more comfortable.", "q"),
    W("Say great, and suggest meeting at ten.", "Great! Shall we meet at ten?|Great! Let's meet at ten.", "ten/10",
      "Great! We meet at the ten? :: Suggest: Shall we meet at ten? No 'the'.", "Great! Shall we meet in ten? :: Times: at ten."),
  ], bye: "Yes, that works for me!" });

UNIT({ unit: 7, name: "Food and everyday things", icon: "🍎", who: "Flatmate", face: "👩", client: "Friend", cface: "👦",
  turns: [
    T("We need lunch for four people. What have you got?", "Say you've got bread, rice and two apples.", "I've got some bread, some rice and two apples.|I've got bread, rice and two apples.", "bread ; rice ; apple",
      "I've got some breads, some rices and two apples. :: Bread and rice are uncountable: no -s.", "I've got a bread, a rice and two apples. :: Uncountable: some bread, some rice."),
    T("I've got four tomatoes and a bottle of water. Have we got any cheese?", "Say no, we haven't got any cheese.", "No, we haven't got any cheese.|No, we haven't.", "no ; havent/have not",
      "No, we haven't got some cheese. :: In negatives use 'any': we haven't got any cheese.", "No, we don't have got cheese. :: Say: we haven't got any cheese."),
    T("OK. How many apples do we need?", "Say you need two more apples.", "We need two more apples.|We need four, so two more.", "two/2 ; more",
      "We need two apples more. :: Say 'two more apples'.", "We need much apples. :: Countable: many apples. Better: two more apples."),
    T("And how much rice do we need?", "Say: two small portions.", "Two small portions.|We need two small portions.", "two/2 ; portion",
      "Two portions smalls. :: Adjectives go first and have no -s: two small portions.", "Two little portion. :: Say 'two small portions'."),
  ], end: "Perfect. I'll write the shopping list. We've got £10.",
  staff: [
    W("Say you need lunch for four people. Ask what your friend has got.", "We need lunch for four people. What have you got?", "four/4 ; what",
      "We need lunch for four persons. What you have got? :: Say 'people', and: What have you got?", "We need lunch for four people. What have you? :: Say: What have you got?", "q"),
    W("Say you've got four tomatoes and a bottle of water. Ask if you've got any cheese.", "I've got four tomatoes and a bottle of water. Have we got any cheese?", "tomato ; water ; cheese",
      "I've got four tomatoes and a water. Have we got some cheese? :: Say 'a bottle of water', and in questions 'any'.", "I have four tomatos and a bottle of water. We have cheese? :: Spelling: tomatoes. Question: Have we got any cheese?", "q"),
    W("Say OK. Ask how many apples you need.", "OK. How many apples do we need?", "how many ; apple",
      "OK. How much apples do we need? :: Countable: how many.", "OK. How many apples we need? :: Questions need 'do': do we need.", "q"),
    W("Ask how much rice you need.", "And how much rice do we need?|How much rice do we need?", "how much ; rice",
      "How many rice do we need? :: Uncountable: how much.", "How much rice we need? :: Questions need 'do': do we need.", "q"),
    W("Say perfect: you'll write the shopping list. You've got £10.", "Perfect. I'll write the shopping list. We've got £10.|Perfect. I'll write the shopping list. We've got ten pounds.", "list ; 10/ten",
      "Perfect. I write the list of the shopping. :: Say: I'll write the shopping list.", "Perfect. I'll write the shopping list. We have got 10 pound. :: £10 = ten pounds."),
  ], bye: "Great, thanks!" });

UNIT({ unit: 8, name: "Where were you yesterday?", icon: "📅", who: "Classmate", face: "👩", client: "Friend", cface: "👨",
  turns: [
    T("Hi! Where were you yesterday morning?", "Say you were at the library at ten.", "I was at the library at ten.|At ten I was at the library.", "was ; library",
      "I were at the library at ten. :: With I: I was.", "I am at the library yesterday. :: Past: I was."),
    T("Was it busy?", "Say no, it wasn't. It was quiet, and you were happy.", "No, it wasn't. It was quiet and I was happy.|No, it wasn't. It was quiet. I was happy there.", "wasnt/was not ; quiet ; happy",
      "No, it wasn't busy, was quiet. :: It needs a subject: it was quiet.", "No, it weren't. It was quiet. :: With it: wasn't."),
    T("Nice. I was at the market. Where were you at three o'clock?", "Say you were at home, and you were tired.", "I was at home. I was tired.|At three I was at home, and I was tired.", "home ; tired",
      "I was in home. I was tired. :: Say 'at home'.", "I was at the home. I was tired. :: Say 'at home' (no 'the')."),
    T("Oh! I was at Oxford at three. It was great.", "Ask if the class was good.", "Was the class good?|Was it a good class?", "was ; class",
      "The class was good? :: Question: Was the class good?", "Were the class good? :: With the class (it): Was.", "q"),
  ], end: "Yes, it was. We practised the past!",
  staff: [
    W("Ask where your friend was yesterday morning.", "Hi! Where were you yesterday morning?|Where were you yesterday morning?", "where ; were ; yesterday",
      "Where was you yesterday morning? :: With you: were.", "Where you were yesterday morning? :: Question order: Where were you…?", "q"),
    W("Ask if it was busy.", "Was it busy?|Was the library busy?", "was ; busy",
      "It was busy? :: Question: Was it busy?", "Were it busy? :: With it: Was it…?", "q"),
    W("Say nice. You were at the market. Ask where they were at three o'clock.", "Nice. I was at the market. Where were you at three o'clock?", "market ; where ; three/3",
      "Nice. I was at the market. Where was you at three? :: With you: were.", "Nice. I were at the market. Where were you at three? :: With I: was.", "q"),
    W("Say you were at Oxford at three. It was great.", "I was at Oxford at three. It was great.|Oh! I was at Oxford at three, and it was great.", "oxford ; great/good",
      "I was in Oxford at three. Was great. :: It needs a subject: It was great.", "I were at Oxford at three. It was great. :: With I: was."),
    W("Say yes, it was. You practised the past.", "Yes, it was. We practised the past!|Yes, it was. We practised the past tense.", "yes ; was",
      "Yes, it were. :: With it: was.", "Yes, was. :: Short answer: Yes, it was."),
  ], bye: "Cool! See you tomorrow." });

UNIT({ unit: 9, name: "A good day", icon: "😊", who: "Friend", face: "👦", client: "Classmate", cface: "👩",
  turns: [
    T("Hi! What did you do on Sunday?", "Say you visited a friend and you cooked lunch.", "I visited a friend and we cooked lunch.|I visited a friend and I cooked lunch.", "visited ; cooked",
      "I visit a friend and cook lunch. :: Past: visited, cooked.", "I did visit a friend and cooked lunch. :: Positive past: I visited (no 'did')."),
    T("Nice! Did you watch TV?", "Say no, you didn't. You studied English.", "No, I didn't. I studied English.|No, I didn't. I studied English in the evening.", "didnt/did not ; studied",
      "No, I didn't watched TV. :: After 'didn't' use the base verb: watch.", "No, I didn't. I studyed English. :: Spelling: study → studied."),
    T("I walked in the park and I watched a film.", "Ask if they called a friend.", "Did you call a friend?|Did you call your friends?", "did ; call",
      "Did you called a friend? :: After 'did' use the base verb: call.", "You called a friend? :: Question: Did you call…?", "q"),
    T("Yes, I did. I called my sister. What did you cook?", "Say you cooked pasta.", "I cooked pasta.|We cooked pasta.", "cooked ; pasta",
      "I cook pasta. :: Past: cooked.", "I did cooked pasta. :: Say: I cooked pasta."),
  ], end: "Yum! Good Sunday, then.",
  staff: [
    W("Ask what your classmate did on Sunday.", "Hi! What did you do on Sunday?|What did you do on Sunday?", "what ; did ; sunday",
      "What did you on Sunday? :: Don't forget 'do': What did you do?", "What you did on Sunday? :: Question: What did you do…?", "q"),
    W("Say nice. Ask if they watched TV.", "Nice! Did you watch TV?", "did ; watch",
      "Nice! Did you watched TV? :: After 'did' use 'watch'.", "Nice! You watched TV? :: Question: Did you watch…?", "q"),
    W("Say you walked in the park and watched a film.", "I walked in the park and I watched a film.|I walked in the park and watched a film.", "walked ; watched",
      "I walk in the park and watch a film. :: Past: walked, watched.", "I was walk in the park and watched a film. :: Past simple: I walked."),
    W("Say yes, you called your sister. Ask what they cooked.", "Yes, I did. I called my sister. What did you cook?", "called ; what ; cook",
      "Yes, I did. I call my sister. What did you cook? :: Past: called.", "Yes, I did. I called my sister. What did you cooked? :: After 'did' use 'cook'.", "q"),
    W("Say yum! It was a good Sunday.", "Yum! Good Sunday, then.|Yum! It was a good Sunday.", "good ; sunday",
      "Yum! Was a good Sunday. :: Add 'it': It was a good Sunday.", "Yum! It is a good Sunday yesterday. :: Past: It was."),
  ], bye: "Yes, it was! Bye!" });

UNIT({ unit: 10, name: "Then and now", icon: "🏫", who: "New classmate", face: "👧", client: "Classmate", cface: "👨",
  turns: [
    T("Hi! I'm new here. Was there a lift in the old building?", "Say no, there wasn't. There were stairs.", "No, there wasn't. There were stairs.|No, there wasn't. We had stairs.", "wasnt/was not ; stairs",
      "No, there weren't a lift. :: One lift: there wasn't.", "No, there wasn't. There was stairs. :: Plural: there were stairs."),
    T("How many classrooms were there?", "Say there were two classrooms.", "There were two classrooms.|There were two.", "were ; two/2",
      "There was two classrooms. :: Plural: there were.", "Had two classrooms. :: Say: There were two classrooms."),
    T("And was the entrance big?", "Say no, it was small.", "No, it wasn't. It was small.|No, the entrance was small.", "small",
      "No, it were small. :: With it: was.", "No, was small. :: It needs a subject: it was small."),
    T("Did you have to use the stairs every day?", "Say yes: you had to use them.", "Yes, I did. We had to use them every day.|Yes, we had to use the stairs.", "had to",
      "Yes, we must use them. :: Past obligation: had to.", "Yes, we have to use them. :: Past: had to."),
  ], end: "Now there's a lift and a wide entrance. Much better!",
  staff: [
    W("Say you're new. Ask if there was a lift in the old building.", "Hi! I'm new here. Was there a lift in the old building?", "was there ; lift",
      "Hi! I'm new. There was a lift in the old building? :: Question: Was there a lift…?", "Hi! I'm new. Were there a lift in the old building? :: One lift: Was there…?", "q"),
    W("Ask how many classrooms there were.", "How many classrooms were there?", "how many ; classroom ; were",
      "How many classrooms there were? :: Question: …were there?", "How much classrooms were there? :: Countable: how many.", "q"),
    W("Ask if the entrance was big.", "And was the entrance big?|Was the entrance big?", "was ; entrance ; big",
      "And the entrance was big? :: Question: Was the entrance big?", "And were the entrance big? :: One entrance: was.", "q"),
    W("Ask if they had to use the stairs every day.", "Did you have to use the stairs every day?", "did ; have to ; stairs",
      "Did you had to use the stairs every day? :: After 'did': have to.", "Had you to use the stairs every day? :: Say: Did you have to…?", "q"),
    W("Say now there's a lift and a wide entrance. Much better!", "Now there's a lift and a wide entrance. Much better!|Now there is a lift and a wide entrance. It's much better!", "lift ; entrance ; better",
      "Now there are a lift and a wide entrance. More better! :: One lift: there's. And say 'much better'.", "Now have a lift and a wide entrance. Much better! :: Say: Now there's a lift…"),
  ], bye: "Yes, it's great!" });

UNIT({ unit: 11, name: "Dates and useful numbers", icon: "🎟️", who: "Receptionist", face: "💁‍♀️", client: "Visitor", cface: "👨",
  turns: [
    T("Good morning! How can I help?", "Say you'd like to book two tickets for 14 November.", "I'd like to book two tickets for the fourteenth of November, please.|I'd like to book two tickets for 14 November, please.", "book ; two/2 ; 14/fourteenth ; november",
      "I want two tickets for the fourteen of November. :: Say 'I'd like to book…', and dates: the fourteenth.", "I'd like to reserve two ticket for the 14 of November. :: Plural: two tickets. Dates: the fourteenth of November.", "p"),
    T("Of course. The visit starts at 10:30, and you arrive at 10:15. Is that OK?", "Say yes, that's fine. Ask how much it is altogether.", "Yes, that's fine. How much is it altogether?|Yes, that's OK. How much is that altogether?", "how much",
      "Yes, is fine. How much costs? :: Say: How much is it?", "Yes, that's fine. How many is it? :: For prices: how much.", "q"),
    T("Tickets are £12.50 each, so that's £25.", "Say OK. Ask for the reference number.", "OK. What's the reference number, please?|OK. Could I have the reference number, please?", "reference",
      "OK. Give me the reference number. :: Too direct: Could I have…, please?", "OK. Which is the reference number? :: Say: What's the reference number?", "pq"),
    T("It's four, eight, two, six.", "Check it: repeat the number.", "Let me check: four, eight, two, six.|So that's four eight two six?", "four/4/4826 ; eight/8/4826 ; two/2/4826 ; six/6/4826",
      "Let me check: four, eight, six, two. :: Listen again: 4-8-2-6.", "Let me to check: four, eight, two, six. :: No 'to': Let me check."),
  ], end: "That's right. See you on the fourteenth of November!",
  staff: [
    W("Greet the visitor and ask how you can help.", "Good morning! How can I help?|Good morning! How can I help you?", "help",
      "Good morning! What do you want? :: Too direct: How can I help?", "Good morning! How I can help? :: Question order: How can I help?", "q"),
    W("Say the visit starts at 10:30, and they arrive at 10:15. Ask if that's OK.", "Of course. The visit starts at 10:30, and you arrive at 10:15. Is that OK?|The visit starts at half past ten, and you arrive at quarter past ten. Is that OK?", "10 30/half past ten/ten thirty ; 10 15/quarter past ten/ten fifteen ; ok/okay/fine/alright",
      "The visit start at 10:30. You arrive at 10:15. Is OK? :: 'The visit starts' (with -s), and 'Is that OK?'.", "The visit starts to 10:30, and you arrive at 10:15. Is that OK? :: Times: at 10:30.", "q"),
    W("Say tickets are £12.50 each, so it's £25.", "Tickets are £12.50 each, so that's £25.|They're twelve pounds fifty each, so that's twenty-five pounds.", "12 50/twelve pounds fifty/twelve fifty ; 25/twenty five",
      "Tickets are £12.50 each one, so are £25. :: Say: so that's £25.", "Tickets are twelve pound fifty each, so that's twenty-five pound. :: Plural: pounds."),
    W("Say the reference number: 4826.", "It's four, eight, two, six.|The reference is 4826.", "4/four/4826 ; 8/eight/4826 ; 2/two/4826 ; 6/six/4826",
      "Is four, eight, two, six. :: It needs a subject: It's…", "Are four, eight, two, six. :: Say: It's four, eight, two, six."),
    W("Say that's right. See you on the 14th of November.", "That's right. See you on the fourteenth of November!|That's right. See you on 14 November!", "right/correct ; see ; 14/fourteenth",
      "That's right. See you the fourteen of November! :: Dates: on the fourteenth.", "Is right. See you on 14 November. :: Say 'That's right'."),
  ], bye: "Thank you! Goodbye!" });

/* ===================== MODULE 3 / Plans, interests and journeys ===================== */
UNIT({ unit: 12, name: "Plans for the coming week", icon: "🎵", who: "Receptionist", face: "👨‍💼", client: "Student", cface: "👩",
  turns: [
    T("Hi! Would you like to join an activity next week?", "Say yes. Ask when the activities will be.", "Yes, please. When will the activities be?|Yes! When will they be?", "when ; will",
      "Yes. When the activities will be? :: Question: When will the activities be?", "Yes. When are going to be? :: Say: When will they be?", "q"),
    T("The conversation class will be on Tuesday at 10:30, and music will be on Thursday at 14:00.", "Say you'll be free on Thursday afternoon.", "I'll be free on Thursday afternoon.|I'll be free on Thursday, in the afternoon.", "free ; thursday",
      "I will free on Thursday afternoon. :: Don't forget 'be': I'll be free.", "I'll be free the Thursday afternoon. :: Days: on Thursday."),
    T("Great. Do you enjoy music?", "Say yes, you do. Ask if there will be seats.", "Yes, I do. Will there be seats?|Yes, I do. Will there be any seats?", "will there ; seat",
      "Yes, I do. There will be seats? :: Question: Will there be seats?", "Yes, I enjoy. Will be seats? :: Say: Yes, I do. Will there be seats?", "q"),
    T("Yes, there will. So, Thursday at two?", "Say yes, you'll come to the music class.", "Yes, I'll come to the music class.|Yes, I'll be there.", "yes ; come/there",
      "Yes, I come to the music class. :: For a decision now: I'll come.", "Yes, I'll coming to the music class. :: After 'will' use the base verb: come."),
  ], end: "Perfect. See you on Thursday!",
  staff: [
    W("Ask if the student would like to join an activity next week.", "Hi! Would you like to join an activity next week?", "would you like ; next week",
      "Hi! Would you like join an activity next week? :: Add 'to': Would you like to join…?", "Hi! You would like to join an activity next week? :: Question order: Would you like…?", "q"),
    W("Say conversation is on Tuesday at 10:30, and music is on Thursday at 14:00. Use 'will be'.", "The conversation class will be on Tuesday at 10:30, and music will be on Thursday at 14:00.", "will be ; tuesday ; thursday",
      "The conversation class will is on Tuesday and music on Thursday. :: will + be: will be.", "Conversation will be the Tuesday and music the Thursday. :: Days: on Tuesday, on Thursday."),
    W("Say great. Ask if they enjoy music.", "Great. Do you enjoy music?|Great. Do you like music?", "do you ; music",
      "Great. You enjoy music? :: Question: Do you enjoy music?", "Great. Are you enjoy music? :: Say: Do you enjoy…?", "q"),
    W("Say yes, there will. Ask: Thursday at two?", "Yes, there will. So, Thursday at two?|Yes, there will. So, Thursday at 2?", "will ; thursday ; two/2/14",
      "Yes, will. So, Thursday at two? :: Short answer: Yes, there will.", "Yes, there will. So, the Thursday at the two? :: No 'the': Thursday at two.", "q"),
    W("Say perfect, see you on Thursday.", "Perfect. See you on Thursday!|Great. See you on Thursday!", "see ; thursday",
      "Perfect. See you the Thursday! :: Days: on Thursday.", "Perfect. We see on Thursday! :: Say 'See you…'."),
  ], bye: "See you! Thanks!" });

UNIT({ unit: 13, name: "Weather and travel", icon: "🌦️", who: "Friend", face: "👩", client: "Classmate", cface: "👨",
  turns: [
    T("Let's visit the garden on Saturday! What will the weather be like?", "Say it'll be cloudy in the morning and sunny in the afternoon.", "It'll be cloudy in the morning and sunny in the afternoon.|It will be cloudy in the morning and sunny in the afternoon.", "cloudy ; sunny",
      "Will be cloudy in the morning and sunny in the afternoon. :: Weather needs 'it': It'll be…", "It will be cloud in the morning and sun in the afternoon. :: Adjectives: cloudy, sunny."),
    T("And in the evening?", "Say it'll rain after five.", "It'll rain after five.|It will be rainy after five.", "rain ; five/5/17",
      "Will rain after five. :: Weather needs 'it': It'll rain.", "It will raining after five. :: After 'will' use the base verb: rain."),
    T("OK. The garden opens at ten, and the cafe opens at half past ten. When can we go?", "Suggest going at eleven.", "We can go at eleven.|Let's go at eleven.", "eleven/11",
      "We can go to eleven. :: Times: at eleven.", "We can going at eleven. :: After 'can' use the base verb: go."),
    T("Good idea. What shall we bring?", "Say: let's bring an umbrella and a raincoat.", "Let's bring an umbrella and a raincoat.|Let's take an umbrella and a raincoat.", "umbrella ; raincoat/coat",
      "Let's bring a umbrella and a raincoat. :: Before a vowel sound: an umbrella.", "Let's to bring an umbrella and a raincoat. :: After 'Let's' no 'to': Let's bring."),
  ], end: "Perfect. There are seats inside the cafe too.",
  staff: [
    W("Suggest visiting the garden on Saturday. Ask what the weather will be like.", "Let's visit the garden on Saturday! What will the weather be like?", "garden ; weather",
      "Let's visit the garden on Saturday! How will the weather be like? :: Say: What will the weather be like?", "Let's visit the garden on Saturday! What will be the weather like? :: Word order: What will the weather be like?", "q"),
    W("Ask about the evening.", "And in the evening?|What about the evening?", "evening",
      "And at the evening? :: Say 'in the evening'.", "And the evening how? :: Say: And in the evening?", "q"),
    W("Say the garden opens at ten and the cafe at half past ten. Ask when you can go.", "OK. The garden opens at ten, and the cafe opens at half past ten. When can we go?", "ten/10 ; when",
      "The garden open at ten. When we can go? :: 'opens' (with -s), and: When can we go?", "The garden opens at ten. When can we to go? :: After 'can' no 'to': go.", "q"),
    W("Say good idea. Ask what you should bring.", "Good idea. What shall we bring?|Good idea. What should we bring?", "what ; bring/take",
      "Good idea. What we bring? :: Say: What shall we bring?", "Good idea. What shall we to bring? :: No 'to' after 'shall'.", "q"),
    W("Say perfect. There are seats inside the cafe too.", "Perfect. There are seats inside the cafe too.|Perfect. The cafe has got seats inside too.", "seats",
      "Perfect. There is seats inside the cafe too. :: Plural: there are seats.", "Perfect. Have seats inside the cafe too. :: Say: There are seats…"),
  ], bye: "Great! See you on Saturday." });

UNIT({ unit: 14, name: "Making plans together", icon: "📝", who: "Friend", face: "👨", client: "Classmate", cface: "👩",
  turns: [
    T("Shall we visit the museum on Thursday? We can meet at ten.", "Say you have an appointment until 10:15. Suggest half past ten instead.", "Sorry, I have an appointment until quarter past ten. What about half past ten instead?|Sorry, I've got an appointment until 10:15. What about 10:30 instead?", "appointment ; half past ten/10 30/ten thirty",
      "I have a cita until 10:15. What about 10:30? :: 'Cita' = appointment.", "I have an appointment until 10:15. And to half past ten? :: Suggest with 'What about…?'."),
    T("Yes, that works for me. I'll bring the timetable.", "Say thanks. Offer to bring water.", "Thanks! I'll bring water.|Great, thanks. I'll bring some water.", "bring ; water",
      "Thanks! I bring the water. :: For an offer now: I'll bring water.", "Thanks! I will to bring water. :: After 'will' no 'to': bring."),
    T("Shall we meet at the museum entrance?", "Say yes, that works for you.", "Yes, that works for me.|Yes, that's fine.", "works/fine/good/great/perfect/ok/okay",
      "Yes, that work for me. :: That works (with -s).", "Yes, is good for me. :: Say: that works for me."),
    T("Great. Don't be late!", "Promise you won't arrive late.", "Don't worry, I won't arrive late.|I won't be late!", "wont/will not",
      "Don't worry, I will not to arrive late. :: After 'will not' no 'to': arrive.", "Don't worry, I don't arrive late. :: For a promise: I won't arrive late."),
  ], end: "See you on Thursday at half past ten!",
  staff: [
    W("Suggest visiting the museum on Thursday. Say you can meet at ten.", "Shall we visit the museum on Thursday? We can meet at ten.", "museum ; thursday ; ten/10",
      "We visit the museum the Thursday? :: Suggest: Shall we visit…? And 'on Thursday'.", "Shall we to visit the museum on Thursday? :: After 'shall we' no 'to': visit.", "q"),
    W("Say yes, that works for you. Offer to bring the timetable.", "Yes, that works for me. I'll bring the timetable.", "bring ; timetable",
      "Yes, that works for me. I bring the timetable. :: Offers: I'll bring.", "Yes, that work for me. I'll bring the timetable. :: That works (with -s)."),
    W("Ask if you can meet at the museum entrance.", "Shall we meet at the museum entrance?", "meet ; entrance",
      "We meet at the museum entrance? :: Suggest: Shall we meet…?", "Shall we meeting at the museum entrance? :: After 'shall we' use the base verb: meet.", "q"),
    W("Say great. Tell them: don't be late!", "Great. Don't be late!", "dont/do not ; late",
      "Great. Not be late! :: Say: Don't be late!", "Great. Don't arrive tard! :: 'Tarde' = late."),
    W("Say see you on Thursday at half past ten.", "See you on Thursday at half past ten!|See you on Thursday at 10:30!", "see ; thursday ; half past ten/10 30/ten thirty",
      "See you the Thursday at ten and half! :: On Thursday, at half past ten.", "We see on Thursday at half past ten! :: Say 'See you…'."),
  ], bye: "See you!" });

