UNIT({ unit: 18, name: "At home and in the neighbourhood", icon: "🏡", who: "Neighbour", face: "👵", client: "New neighbour", cface: "👨",
  turns: [
    T("Hello! Would you like to come for coffee on Saturday?", "Accept: say yes, you'd love to.", "Yes, I'd love to. Thank you!|Yes, I'd love to!", "love/like/great",
      "Yes, I'd love. :: Say 'I'd love to'.", "Yes, I love. :: Say 'I'd love to'."),
    T("Wonderful. There's a garden behind the house, and a living room downstairs.", "Ask what you'll do if it rains.", "What will we do if it rains?|And what will we do if it rains?", "if ; rain",
      "What will we do if it will rain? :: After 'if' use the present: if it rains.", "What we do if it rains? :: Say: What will we do…?", "q"),
    T("If it rains, we'll sit in the living room. Coffee or tea?", "Say you'd prefer tea, please.", "I'd prefer tea, please.|Tea, please.", "tea",
      "I want tea. :: Too direct: Tea, please.", "I prefer the tea. :: No 'the': I'd prefer tea, please.", "p"),
    T("No problem. Do you need anything else?", "Ask if there's an entrance with no stairs.", "Is there an entrance with no stairs?|Is there an entrance without stairs?", "is there ; entrance",
      "There is an entrance without stairs? :: Question: Is there…?", "Is there a entrance with no stairs? :: Before a vowel sound: an entrance.", "q"),
  ], end: "Yes, there is. Use the side door. See you on Saturday!",
  staff: [
    W("Invite your neighbour for coffee on Saturday.", "Hello! Would you like to come for coffee on Saturday?", "would you like ; coffee ; saturday",
      "Hello! You want come for coffee on Saturday? :: Say: Would you like to come…?", "Hello! Would you like to come to take a coffee on Saturday? :: Say 'come for coffee'.", "q"),
    W("Say there's a garden behind the house, and a living room downstairs.", "Wonderful. There's a garden behind the house, and a living room downstairs.", "garden ; living room",
      "Wonderful. There are a garden behind the house. :: One garden: there's.", "Wonderful. Have a garden behind the house and a living room downstairs. :: Say: There's a garden…"),
    W("Say if it rains, you'll sit in the living room. Ask: coffee or tea?", "If it rains, we'll sit in the living room. Coffee or tea?", "if ; rain ; coffee ; tea",
      "If it will rain, we'll sit in the living room. Coffee or tea? :: After 'if' use the present: If it rains.", "If it rains, we sit in the living room. Coffee or tea? :: The result: we'll sit.", "q"),
    W("Say no problem. Ask if they need anything else.", "No problem. Do you need anything else?|No problem. Is there anything else you need?", "anything ; else",
      "No problem. You need something more? :: Say: Do you need anything else?", "No problem. Do you need anything other? :: Say 'anything else'.", "q"),
    W("Say yes, there is: use the side door. See you on Saturday!", "Yes, there is. Use the side door. See you on Saturday!", "side ; saturday",
      "Yes, there is. Use the door of the side. See you on Saturday! :: Say 'the side door'.", "Yes, there's. Use the side door. See you on Saturday! :: Short answer: Yes, there is."),
  ], bye: "Lovely. See you then!" });

UNIT({ unit: 19, name: "People and helpful choices", icon: "🙏", who: "Classmate", face: "👩", client: "Friend", cface: "👨",
  turns: [
    T("Hi! Shall we meet on Friday at ten?", "Say sorry, ten is impossible for you. You have an appointment until 10:30.", "I'm sorry, ten is impossible for me. I have an appointment until 10:30.|Sorry, that time is impossible for me. I've got an appointment until half past ten.", "sorry ; impossible ; appointment",
      "Sorry, ten is unpossible for me. I have an appointment until 10:30. :: The opposite of 'possible' is 'impossible'.", "Sorry, I can't at ten. I have a cita until 10:30. :: 'Cita' = appointment."),
    T("No problem. What time works for you?", "Ask: is it possible to meet at eleven?", "Is it possible to meet at eleven?|Is it possible to meet at 11?", "possible ; eleven/11",
      "It is possible to meet at eleven? :: Question: Is it possible…?", "Is possible meet at eleven? :: Say: Is it possible to meet…?", "q"),
    T("Yes, eleven is fine.", "Thank them for being flexible.", "Thank you for being flexible.|Thanks for being so flexible!", "thank ; flexible",
      "Thank you for be flexible. :: After 'for' use -ing: being.", "Thank you to be flexible. :: Say: Thank you for being flexible."),
    T("You're welcome! So, Friday at eleven at the cafe?", "Confirm: yes, Friday at eleven.", "Yes, Friday at eleven. See you there!|Yes, that's right. Friday at eleven.", "yes ; friday ; eleven/11",
      "Yes, the Friday at the eleven. :: No 'the': Friday at eleven.", "Yes, Friday to eleven. :: Times: at eleven."),
  ], end: "Great. See you on Friday!",
  staff: [
    W("Ask if your friend can meet on Friday at ten.", "Hi! Shall we meet on Friday at ten?|Can we meet on Friday at ten?", "friday ; ten/10",
      "Hi! We meet the Friday at ten? :: Suggest: Shall we meet on Friday…?", "Hi! Shall we meet on Friday at the ten? :: Times: at ten (no 'the').", "q"),
    W("Say no problem. Ask what time works for them.", "No problem. What time works for you?", "what time ; work",
      "No problem. What time work for you? :: What time works (with -s).", "No problem. Which hour is good for you? :: Say: What time works for you?", "q"),
    W("Say yes, eleven is fine.", "Yes, eleven is fine.|Yes, 11 is fine.", "eleven/11 ; fine/ok/okay/good/great/perfect",
      "Yes, eleven are fine. :: Say 'eleven is fine'.", "Yes, the eleven is fine. :: No 'the' with times."),
    W("Say you're welcome. Check: Friday at eleven at the cafe?", "You're welcome! So, Friday at eleven at the cafe?", "friday ; eleven/11 ; cafe/caf",
      "Your welcome! So, Friday at eleven at the cafe? :: You're (you are) welcome.", "You're welcome! So, the Friday at eleven in the cafe? :: Say 'Friday… at the cafe'.", "q"),
    W("Say great, see you on Friday.", "Great. See you on Friday!", "see ; friday",
      "Great. See you the Friday! :: Days: on Friday.", "Great. We see on Friday! :: Say 'See you…'."),
  ], bye: "Bye! Thanks again." });

UNIT({ unit: 20, name: "Everyday rules and choices", icon: "🖼️", who: "Gallery assistant", face: "👨‍💼", client: "Visitor", cface: "👩",
  turns: [
    T("Welcome to the gallery! Can I see your ticket?", "Ask if you have to print your ticket.", "Do I have to print my ticket?|Do I have to print it?", "have to ; print",
      "I have to print my ticket? :: Question: Do I have to…?", "Must I to print my ticket? :: Say: Do I have to print…?", "q"),
    T("No, you don't. A phone ticket is fine.", "Ask if you can use flash.", "Can I use flash?|Am I allowed to use flash?", "flash",
      "I can use flash? :: Question: Can I use…?", "Can I to use flash? :: After 'can' no 'to': use.", "q"),
    T("No. You mustn't use flash in this gallery.", "Ask if you have to do the guided tour.", "Do I have to do the guided tour?|Is the guided tour required?", "tour",
      "I have to do the guided tour? :: Question: Do I have to…?", "Is obligatory the guided tour? :: Say: Do I have to do the guided tour?", "q"),
    T("No, you don't have to. It's optional. It starts at twelve.", "Check the rules: no flash, and the tour is optional.", "So, I mustn't use flash, and the tour is optional.|So, no flash, and I don't have to do the tour.", "flash ; tour",
      "So, I don't have to use flash, and the tour is optional. :: Careful: flash is prohibited: you mustn't use flash.", "So, I can use flash, and I mustn't do the tour. :: Careful: no flash, and the tour is optional (you don't have to)."),
  ], end: "That's right. Enjoy the gallery!",
  staff: [
    W("Welcome the visitor. Ask to see their ticket.", "Welcome to the gallery! Can I see your ticket?|Welcome! Can I see your ticket, please?", "ticket",
      "Welcome to the gallery! Give me your ticket. :: Too direct: Can I see your ticket?", "Welcome to the gallery! I can see your ticket? :: Question: Can I see…?", "q"),
    W("Say no, they don't have to print it. A phone ticket is fine.", "No, you don't. A phone ticket is fine.|No, you don't have to. A ticket on your phone is fine.", "dont/do not ; phone",
      "No, you mustn't. A phone ticket is fine. :: 'Mustn't' = it's prohibited. Here it's optional: you don't have to.", "No, you not have to. A phone ticket is fine. :: Say: you don't have to."),
    W("Say no: they mustn't use flash in this gallery.", "No. You mustn't use flash in this gallery.|No, sorry. You mustn't use flash here.", "mustnt/must not ; flash",
      "No. You don't have to use flash. :: For a prohibition: you mustn't.", "No. You mustn't to use flash. :: After 'mustn't' no 'to': use."),
    W("Say they don't have to: the tour is optional. It starts at twelve.", "No, you don't have to. It's optional. It starts at twelve.|It's optional. The tour starts at twelve.", "optional ; twelve/12",
      "You mustn't do it. It's optional. It starts at twelve. :: Optional: you don't have to.", "It's optional. It start at twelve. :: It starts (with -s)."),
    W("Say that's right. Enjoy the gallery!", "That's right. Enjoy the gallery!", "enjoy",
      "That's right. Enjoy of the gallery! :: Say 'Enjoy the gallery' (no 'of').", "Is right. Enjoy the gallery! :: Say 'That's right'."),
  ], bye: "Thank you!" });

